size_t fn_18(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap)
{
 size_t i = 0, d = 0, q = 0;
 uint8_t st[64];

 while (i < len) {
  uint8_t c = in[i];

  if (q == 2)
   q = 1;
  else if (q == 1) {
   if (c == '\\')
    q = 2;
   else if (c == '"')
    q = 0;
  } else if (c == '"')
   q = 1;
  else if (c == '(' || c == '[' || c == '{') {
   if (d == 64)
    return i + 1;
   if (c == '(')
    c = ')';
   else
    c += 2;
   st[d++] = c;
  } else if (c == ')' || c == ']' || c == '}') {
   if (d == 0 || c != st[d - 1])
    return i + 1;
   d--;
  }
  i++;
 }

 if (d == 0 && q == 0)
  return 0;
 return len + 1;
}
